import { execFileSync } from "node:child_process";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

// A one-pixel JPEG fixture, not generated by a provider. All writes are local.
const jpeg = Buffer.from(
	"",
	"base64",
);
const cwd = fileURLToPath(new URL("../", import.meta.url));
const temporary = mkdtempSync(join(tmpdir(), "mordheim-gallery-"));
const key = "image-generation/local-gallery-fixture.jpg";
const run = (...args) =>
	execFileSync("pnpm", ["exec", "wrangler", ...args, "--local"], {
		cwd,
		stdio: "inherit",
	});

try {
	const file = join(temporary, "fixture.jpg");
	writeFileSync(file, jpeg);
	run(
		"r2",
		"object",
		"put",
		`mordheim-generated-images/${key}`,
		"--file",
		file,
		"--content-type",
		"image/jpeg",
	);
	run(
		"d1",
		"execute",
		"mordheim-two-db",
		"--command",
		`
		INSERT INTO image_generation_jobs
			(id, prompt, status, result_key, result_mime_type, result_bytes, result_model, completed_at)
		VALUES ('local-gallery-fixture', 'Local test image (one-pixel JPEG; no paid generation)',
			'completed', '${key}', 'image/jpeg', ${jpeg.length}, 'local-fixture',
			strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
		ON CONFLICT(id) DO UPDATE SET completed_at = excluded.completed_at;
	`,
	);
	console.log("Local fixture ready. Start pnpm dev and visit /generated-images.");
} finally {
	rmSync(temporary, { recursive: true, force: true });
}
